#include <stdint.h>
#include "stm32l476xx.h"
#include "bsp_led.h"
#include "timebase.h"

#define RESET_CLOCK_HZ 4000000u

int main(void)
{
    timebase_init(RESET_CLOCK_HZ);
    bsp_led_init();

    while (1)
    {
        bsp_led_toggle();
        delay_ms(500u);
    }
}





